?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CMS Taslak Önizleme</title><style>body{margin:0;background:#f5f2ec;color:#171717;font-family:Inter,Arial,sans-serif}.bar{position:sticky;top:0;z-index:9;background:#111827;color:#fff;padding:12px 18px;display:flex;justify-content:space-between;align-items:center}.bar a{color:#fff}.page{max-width:760px;margin:auto;padding:22px}.block{overflow:hidden;border-radius:22px;margin:18px 0;padding:28px;box-shadow:0 16px 45px #00000010}.block img,.block video{width:100%;max-height:460px;object-fit:cover;border-radius:16px;margin:15px 0}.block h2{font-size:clamp(25px,6vw,42px);margin:0 0 8px}.block p{line-height:1.7}.cta{display:inline-block;padding:12px 16px;background:#111827;color:#fff;text-decoration:none;border-radius:12px;font-weight:800}.empty{text-align:center;padding:80px 20px;color:#64748b}</style></head><body><div class="bar"><strong>Taslak önizleme — müşterilere görünmez</strong><a href="/admin/restaurant-cms/?tab=content">CMS'e dön</a></div><main class="page"><?php if(!$blocks):?><div class="empty">Aktif taslak içerik bloğu bulunmuyor.</div><?php endif;?><?php foreach($blocks as $b): $media=cms_safe_url((string)$b['media_url']);?><section class="block" style="background:<?=ph($b['background_color'])?>;color:<?=ph($b['text_color'])?>"><?php if($b['subtitle']):?><small><?=ph($b['subtitle'])?></small><?php endif;?><?php if($b['title']):?><h2><?=ph($b['title'])?></h2><?php endif;?><?php if($media):?><?php if(preg_match('/\.mp4(?:\?|$)/i',$media)):?><video controls preload="metadata" src="<?=ph($media)?>"></video><?php else:?><img loading="lazy" src="<?=ph($media)?>" alt="<?=ph($b['title'])?>"><?php endif;?><?php endif;?><?php if($b['body']):?><p><?=nl2br(ph($b['body']))?></p><?php endif;?><?php if($b['button_text']&&cms_safe_url((string)$b['button_url'])):?><a class="cta" href="<?=ph(cms_safe_url((string)$b['button_url']))?>"><?=ph($b[